-- Public catalog; only service-role/admin tools can maintain it.
create table public.courses (
 id uuid primary key,
 name text not null,
 locality text not null default '',
 address text not null default '',
 latitude double precision not null check (latitude between -90 and 90),
 longitude double precision not null check (longitude between -180 and 180),
 published boolean not null default false,
 playable boolean not null default false,
 updated_at timestamptz not null default now()
);
create table public.course_tees (
 course_id uuid not null references public.courses(id) on delete cascade,
 name text not null,
 total_yardage integer not null check (total_yardage > 0),
 rating double precision not null check (rating > 0),
 slope integer not null check (slope between 55 and 155),
 primary key(course_id,name)
);
create table public.course_holes (
 course_id uuid not null references public.courses(id) on delete cascade,
 number integer not null check (number between 1 and 18),
 definition jsonb not null check (jsonb_typeof(definition) = 'object' and (definition->>'number')::integer = number),
 primary key(course_id,number)
);
alter table public.courses enable row level security;
alter table public.course_tees enable row level security;
alter table public.course_holes enable row level security;
create policy "Published courses readable" on public.courses for select to anon, authenticated using (published);
create policy "Published tees readable" on public.course_tees for select to anon, authenticated using (exists(select 1 from public.courses where id=course_id and published));
create policy "Published holes readable" on public.course_holes for select to anon, authenticated using (exists(select 1 from public.courses where id=course_id and published));
revoke all on public.courses,public.course_tees,public.course_holes from anon,authenticated;
grant select on public.courses,public.course_tees,public.course_holes to anon,authenticated;
grant all on public.courses,public.course_tees,public.course_holes to service_role;
create view public.course_catalog with (security_invoker = true) as
select c.id,c.name,c.locality,c.address,c.latitude,c.longitude,
case when c.playable and
 (select count(*) from public.course_holes h where h.course_id=c.id)=18 and
 exists(select 1 from public.course_tees t where t.course_id=c.id)
then jsonb_build_object(
 'id',c.id,'name',c.name,'location',c.locality || ' · ' || c.address,
 'coordinate',jsonb_build_object('latitude',c.latitude,'longitude',c.longitude),
 'tees',(select jsonb_agg(jsonb_build_object('name',t.name,'totalYardage',t.total_yardage,'rating',t.rating,'slope',t.slope) order by t.total_yardage desc) from public.course_tees t where t.course_id=c.id),
 'holes',(select jsonb_agg(h.definition order by h.number) from public.course_holes h where h.course_id=c.id)
) else null end as definition
from public.courses c where c.published;
grant select on public.course_catalog to anon,authenticated,service_role;

